# High privilege keywords and patterns
high_privilege_principals := {"root", "administrator", "system", "admin", "Administrator", "ROOT", "SYSTEM"}
wildcard_patterns := {"*", "**", ".*", "*:*", "arn:*"}
privileged_flags := {"privileged", "Privileged", "PRIVILEGED"}
assume_role_patterns := {"assume_role", "AssumeRole", "assume-role", "role_assumption", "assumeRole"}
impersonate_patterns := {"impersonate", "impersonation", "Impersonate", "IMPERSONATE"}
elevation_patterns := {"elevation", "elevated", "Elevation", "ELEVATED"}
run_as_patterns := {"run_as", "runAs", "RunAs", "RUN_AS"}
host_namespace_patterns := {"host_network", "hostNetwork", "host_pid", "hostPid", "host_ipc", "hostIpc"}
automount_patterns := {"automount_service_account_token", "automountServiceAccountToken"}
all_projects_patterns := {"all_projects", "all_locations", "all_zones", "all_regions", "global"}

# Check for wildcard permissions
is_wildcard(value) {
    value.ir_type == "String"
    value.value == wildcard_patterns[_]
}

# Check for high privilege principal
is_high_privilege_principal(value) {
    value.ir_type == "String"
    lower(value.value) == lower(high_privilege_principals[_])
}

# Check for privileged flag
is_privileged_flag(value) {
    value.ir_type == "String"
    lower(value.value) == lower(privileged_flags[_])
} else {
    value.ir_type == "Boolean"
    value.value == true
}

# Check for assume role patterns
is_assume_role(value) {
    value.ir_type == "String"
    regex.match("(?i)(assume.?role|role.?assumption)", value.value)
}

# Check for impersonate patterns
is_impersonate(value) {
    value.ir_type == "String"
    regex.match("(?i)(impersonat)", value.value)
}

# Check for elevation patterns
is_elevation(value) {
    value.ir_type == "String"
    regex.match("(?i)(elevat)", value.value)
}

# Check for run_as with high privilege
is_run_as_privileged(attr) {
    attr.name == run_as_patterns[_]
    is_high_privilege_principal(attr.value)
}

# Check for host namespace sharing
is_host_namespace(attr) {
    attr.name == host_namespace_patterns[_]
    is_privileged_flag(attr.value)
}

# Check for automount service account token
is_automount_token(attr) {
    attr.name == automount_patterns[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

# Check for all projects/locations/global scope
is_unbounded_scope(value) {
    value.ir_type == "String"
    regex.match("(?i)(all.?projects|all.?locations|all.?zones|all.?regions|^global$)", value.value)
}

# Check for unbounded namespace
is_unbounded_namespace(attr) {
    attr.name == "namespace"
    value := attr.value
    value.ir_type == "String"
    value.value == "*"
} else {
    attr.name == "namespace"
    value := attr.value
    value.ir_type == "String"
    regex.match("(?i)(kube-system|kube-public|default)", value.value)
}

# Check for excessive capabilities
is_excessive_capability(value) {
    value.ir_type == "String"
    regex.match("(?i)(cap_sys_admin|cap_net_admin|cap_dac_override|cap_dac_read_search|all)", value.value)
}

# Generic attribute name patterns for privilege detection
privilege_attr_names := {
    "user", "User", "USER", "run_as", "runAs", "RunAs", "RUN_AS",
    "execution_role", "ExecutionRole", "task_role", "TaskRole", 
    "instance_profile", "InstanceProfile", "service_account", "ServiceAccount",
    "role", "Role", "iam_role", "IamRole", "principal", "Principal",
    "scope", "Scope", "permissions", "Permissions", "policy", "Policy",
    "capabilities", "Capabilities", "security_context", "SecurityContext",
    "namespace", "Namespace"
}

# Helper to check if attribute name matches privilege patterns
is_privilege_attribute_name(name) {
    privilege_attr_names[_] == name
} else {
    regex.match("(?i)(role|permission|policy|privilege|capability|context|principal|scope|namespace|user)", name)
}

# Recursively check for wildcard in complex values
has_wildcard_in_value(value) {
    is_wildcard(value)
} else {
    value.ir_type == "Array"
    some item
    item := value.value[_]
    has_wildcard_in_value(item)
} else {
    value.ir_type == "Hash"
    some key
    val := value.value[key]
    has_wildcard_in_value(val)
}

# Check for permission/resource wildcards in policy-like structures
has_policy_wildcards(attrs) {
    some attr in attrs
    attr.name == "Action"
    has_wildcard_in_value(attr.value)
} else {
    some attr in attrs
    attr.name == "Resource"
    has_wildcard_in_value(attr.value)
} else {
    some attr in attrs
    attr.name == "Effect"
    attr.value.ir_type == "String"
    lower(attr.value.value) == "allow"
    some other_attr in attrs
    other_attr != attr
    has_wildcard_in_value(other_attr.value)
}

# Main rule: Detect execution with unnecessary privileges - wildcard permissions
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    some attr in attrs

    # Check for wildcard in Action/Resource/Scope attributes
    is_privilege_attribute_name(attr.name)
    has_wildcard_in_value(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Overly permissive wildcard permissions detected in IAM or access configuration. (CWE-250)"
    }
}

